source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    centers = {}
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                centers[(r + 1, c + 1)] = color

    out = [row[:] for row in grid]
    row_lines = {}
    col_lines = {}
    for (r, c), color in centers.items():
        row_lines.setdefault(r, set()).add(color)
        col_lines.setdefault(c, set()).add(color)

    for r, colors in row_lines.items():
        color = next(iter(colors)) if len(colors) == 1 else None
        for c in range(w):
            out[r][c] = color if color is not None else 0
    for c, colors in col_lines.items():
        color = next(iter(colors)) if len(colors) == 1 else None
        for r in range(h):
            out[r][c] = color if color is not None else 0

    # Distinct-colored extended axes leave a blank at their crossings.
    for r, row_colors in row_lines.items():
        for c, col_colors in col_lines.items():
            if any(a != b for a in row_colors for b in col_colors):
                out[r][c] = 0
    return out
'''
